// Normalize whatever shape arrived and classify into a domain + type so the
// Switch node can route it to the right evidence-gathering branch.
const cfg = $input.first().json;
const evt = cfg.body || cfg;

const orderRiskTypes = ['fraud_signal', 'chargeback_risk', 'address_mismatch', 'fulfillment_delay', 'payment_dispute'];
const inventoryPricingTypes = ['low_stock', 'overstock', 'price_drift', 'supplier_cost_change', 'margin_erosion'];

let eventType = evt.eventType || 'unknown';
let eventDomain = 'unknown';

if (orderRiskTypes.includes(eventType)) {
  eventDomain = 'order_risk';
} else if (inventoryPricingTypes.includes(eventType)) {
  eventDomain = 'inventory_pricing';
} else if (evt.orderId) {
  eventDomain = 'order_risk';
  eventType = eventType === 'unknown' ? 'fraud_signal' : eventType;
} else if (evt.sku) {
  eventDomain = 'inventory_pricing';
  eventType = eventType === 'unknown' ? 'low_stock' : eventType;
}

return [{
  json: {
    ...cfg,
    eventDomain,
    eventType,
    orderId: evt.orderId || null,
    customerId: evt.customerId || null,
    sku: evt.sku || null,
    warehouseId: evt.warehouseId || null,
    rawEvent: evt
  }
}];

// Merge either evidence branch into one consistent shape so a single
// Claude prompt node can serve both order-risk and inventory-pricing domains.
const items = $input.all();
const all = items.map(i => i.json);

// Figure out which branch this came from by presence of distinguishing fields
const isOrderRisk = all.some(a => a.orderId && (a.order || a.customerHistory || a.fraudSignals || a[0] || a.id));
const base = all[0] || {};

let evidence = {};
let eventDomain = base.eventDomain;
let eventType = base.eventType;

if (eventDomain === 'order_risk') {
  evidence = {
    order: all[0]?.order || all[0] || {},
    customerHistory: all[1]?.customerHistory || all[1] || {},
    fraudSignals: all[2]?.fraudSignals || all[2] || {}
  };
} else {
  evidence = {
    inventory: all[0]?.inventory || all[0] || {},
    pricingHistory: all[1]?.pricingHistory || all[1] || {},
    marketData: all[2]?.marketData || all[2] || {}
  };
}

return [{
  json: {
    eventDomain,
    eventType,
    orderId: base.orderId,
    customerId: base.customerId,
    sku: base.sku,
    warehouseId: base.warehouseId,
    rawEvent: base.rawEvent,
    commerceApiBaseUrl: base.commerceApiBaseUrl,
    anthropicModel: base.anthropicModel,
    dbTable: base.dbTable,
    slackChannelLowNoise: base.slackChannelLowNoise,
    slackChannelEscalation: base.slackChannelEscalation,
    autoExecuteConfidenceThreshold: base.autoExecuteConfidenceThreshold,
    evidence
  }
}];

const cfg = $('JS - Build Unified Decision Context').first().json;
const response = $input.first().json;

const textBlock = (response.content || []).find(b => b.type === 'text');
let parsed = {};
try {
  const raw = (textBlock?.text || '{}').replace(/```json|```/g, '').trim();
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = {
    parseError: true,
    recommendedAction: 'no_action',
    confidencePercent: 0,
    riskLevel: 'high',
    reasoning: 'Could not parse model response; routed to manual review.',
    suggestedSlackMessage: 'AI decision could not be parsed for event ' + (cfg.orderId || cfg.sku) + '. Manual review required.',
    executionPayload: {}
  };
}

return [{
  json: {
    eventDomain: cfg.eventDomain,
    eventType: cfg.eventType,
    orderId: cfg.orderId,
    customerId: cfg.customerId,
    sku: cfg.sku,
    warehouseId: cfg.warehouseId,
    commerceApiBaseUrl: cfg.commerceApiBaseUrl,
    dbTable: cfg.dbTable,
    slackChannelLowNoise: cfg.slackChannelLowNoise,
    slackChannelEscalation: cfg.slackChannelEscalation,
    autoExecuteConfidenceThreshold: cfg.autoExecuteConfidenceThreshold,
    evidenceSnapshot: cfg.evidence,
    decidedAt: new Date().toISOString(),
    ...parsed
  }
}];

// Combine the decision (from JS - Parse AI Decision, always available on
// $('JS - Parse AI Decision')) with whether auto-execution actually ran,
// so both branches produce one consistent record for logging + Slack.
const decision = $('JS - Parse AI Decision').first().json;
const current = $input.first().json;

const wasAutoExecuted = !!(current.autoExecuted || (current.body && current.body.autoExecuted));

return [{
  json: {
    ...decision,
    autoExecuted: wasAutoExecuted,
    executionResult: wasAutoExecuted ? current : null
  }
}];

